using System.Collections.Generic;
using UnityEngine;

namespace SquashBot.Data
{
    public enum Language
    {
        English,
        Turkish,
        Arabic,
        Spanish,
        German,
        Korean,
        Italian,
        Azerbaijani
    }

    /// <summary>
    /// The game's text in eight languages (English and Turkish here, the others in their own Loc*.cs files). Missing
    /// keys fall back to English, then to the key. Arabic is shaped and laid out right to left by the UI
    /// (<see cref="SquashBot.UI.RtlTextPreprocessor"/>).
    /// </summary>
    public static partial class Loc
    {
        private static Language? current;

        // Read lazily: PlayerPrefs may only be touched from the main thread after startup.
        public static Language Current => current ?? (current = SaveData.Language).Value;

        public static void Set(Language language)
        {
            current = language;
            SaveData.Language = language;
        }

        public static string T(string key)
        {
            var table = Table(Current);
            if (table.TryGetValue(key, out var value)) return value;
            return English.TryGetValue(key, out value) ? value : key;
        }

        /// <summary>A language's own name for itself (for the language list).</summary>
        public static string NameOf(Language language) => Table(language).TryGetValue("lang.name", out var name) ? name : language.ToString();

        public static string F(string key, params object[] args) => string.Format(T(key), args);

        /// <summary>The culture for upper- and lower-casing text in the current language (Turkish dotted İ and dotless I).</summary>
        public static System.Globalization.CultureInfo Culture =>
            Current == Language.Turkish || Current == Language.Azerbaijani ? System.Globalization.CultureInfo.GetCultureInfo("tr-TR") : System.Globalization.CultureInfo.InvariantCulture;

        /// <summary>True when the key has a text in the current language or in English.</summary>
        public static bool Has(string key) => Table(Current).ContainsKey(key) || English.ContainsKey(key);

        /// <summary>The order of the language list.</summary>
        public static readonly Language[] Order =
        {
            Language.Turkish, Language.English, Language.Arabic, Language.Spanish, Language.German, Language.Korean, Language.Italian, Language.Azerbaijani
        };

        public static bool IsRightToLeft => Current == Language.Arabic;

        private static Dictionary<string, string> Table(Language language)
        {
            switch (language)
            {
                case Language.Turkish: return Turkish;
                case Language.Arabic: return Arabic;
                case Language.Spanish: return Spanish;
                case Language.German: return German;
                case Language.Korean: return Korean;
                case Language.Italian: return Italian;
                case Language.Azerbaijani: return Azerbaijani;
                default: return English;
            }
        }

        /// <summary>
        /// Default for first launch: the device's language when the game speaks it, English otherwise. The device's
        /// own locale code is read first (Unity's systemLanguage has no Azerbaijani), then Unity's guess.
        /// </summary>
        public static Language SystemDefault
        {
            get
            {
                switch (DeviceLanguageCode())
                {
                    case "tr": return Language.Turkish;
                    case "az": return Language.Azerbaijani;
                    case "ar": return Language.Arabic;
                    case "es": return Language.Spanish;
                    case "de": return Language.German;
                    case "ko": return Language.Korean;
                    case "it": return Language.Italian;
                    case "en": return Language.English;
                }
                switch (Application.systemLanguage)
                {
                    case SystemLanguage.Turkish: return Language.Turkish;
                    case SystemLanguage.Arabic: return Language.Arabic;
                    case SystemLanguage.Spanish: return Language.Spanish;
                    case SystemLanguage.German: return Language.German;
                    case SystemLanguage.Korean: return Language.Korean;
                    case SystemLanguage.Italian: return Language.Italian;
                    default: return Language.English;
                }
            }
        }

        /// <summary>The device's language as a two-letter code ("tr", "az"...), or "" when it can't be read.</summary>
        private static string DeviceLanguageCode()
        {
            try
            {
#if UNITY_ANDROID && !UNITY_EDITOR
                using (var locale = new AndroidJavaClass("java.util.Locale"))
                using (var current = locale.CallStatic<AndroidJavaObject>("getDefault"))
                    return (current.Call<string>("getLanguage") ?? "").ToLowerInvariant();
#else
                var culture = System.Globalization.CultureInfo.CurrentUICulture;
                return culture == null || culture.Equals(System.Globalization.CultureInfo.InvariantCulture) ? "" : culture.TwoLetterISOLanguageName.ToLowerInvariant();
#endif
            }
            catch
            {
                return "";
            }
        }

