            ["rehber.jump.b"] = "Jump with the JUMP button. A blow struck in the air takes more health than usual and knocks your rival's head off for a moment before it pops back. Your rival can jump and strike too, watch out!",
            ["rehber.defend.t"] = "Hearts and shields",
            ["rehber.defend.b"] = "Every duel you have 3 hearts and 3 shields. A heart gives some of your health back. A shield stops two blows for a few seconds. If you carry a shield from the shop, it also blocks blows from the front; a blocked blow takes no health.",
            ["rehber.stages.t"] = "Duel stages",
            ["rehber.stages.b"] = "There are seven stages: Blue Grove, Glacier Peak, Red Planet, Cappadocia, Blossom Temple, Knights' Court and Desert Palace. One is picked at random each match. In the stands your fans are blue, your rival's are red.",
            ["rehber.sec.progress"] = "PROGRESS",
            ["rehber.chests.t"] = "Duel chests",
            ["rehber.chests.b"] = "Win duels to win chests. Open them with the CHESTS button: weapons, shields or gold come out, and items for your bag. If you don't like it, you can swap the contents once by watching an ad. See what a chest can hold under CONTENTS.",
            ["rehber.rank.t"] = "Trophies and rank",
            ["rehber.rank.b"] = "Win to collect trophies and climb the ranks. Your rank shows on the profile button at the top right; press it to see your matches and stats. A higher rank also makes your army a little stronger.",
            ["rehber.dlevel.t"] = "Duel level",
            ["rehber.dlevel.b"] = "Every duel gives XP: a win 100, a draw 60, a loss 40, the day's first win 100 more, the match's small challenge 50, a comeback win 50. Every level brings gold, every fifth a bronze chest, and levels 10–50 a title.",
            ["rehber.mastery.t"] = "Weapon mastery",
            ["rehber.mastery.b"] = "Every duel with a weapon raises its mastery (a win 3, a loss 1). Its levels bring gold and core parts; from level 7 a badge shows on your card, and at 10 the family's master title.",
            ["rehber.parts.t"] = "Robot parts and cores",
            ["rehber.parts.b"] = "foi grows part by part in the shop's UPGRADES: the Body adds health, the Arms damage, the Shell armour (20 levels each). Levels 1–10 cost gold, 11–20 gold and core parts too. Core parts come from duels (3 a win, 1 a loss), the day's first win, rank-ups and the gold chest. At levels 5, 10, 15 and 20 the part changes how foi looks.",
            ["rehber.ceiling.t"] = "League ceiling",
            ["rehber.ceiling.b"] = "Every rank tier has a ceiling in ranked duels: parts above it count only up to it, and a weapon above the tier's weapon level hits like that level. At the ceiling, skill decides. Rise in rank to lift it. Friend matches are equal power: both sides at the third tier's ceiling.",
            ["rehber.weapons.t"] = "Weapons",
            ["rehber.weapons.b"] = "Four families: swords (fastest), spears (reach), axes (power hit and knockdown 20% stronger) and heavy weapons (biggest blow, every hit staggers). Within a tier every weapon does the same damage a second. Rank weapons stay yours for good.",
            ["rehber.quests.t"] = "Quests",
            ["rehber.quests.b"] = "All quests are on one QUESTS screen: three a day (a duel quest, a level quest and one more of either) and three bigger ones a week. Take the coins of the ones you finish.",
            ["rehber.login.t"] = "Login calendar",
            ["rehber.login.b"] = "Come in every day for a gift: 200 gold, a plain chest, 300 gold, 10 cores, a bronze chest, 500 gold and a gold chest. Miss a day and nothing is lost: the calendar goes on from where you left it. A friend match pays gold for the first three of the day and brings no chest.",
            ["rehber.friends.t"] = "Friends",
            ["rehber.friends.b"] = "Add a friend by name or 6-letter friend code with the FRIENDS button. Online: invite them to a duel; away: fight their copy (no rank points, it counts for your score). Lost? TAKE REVENGE. When someone you invited finishes World 1, you both get a bronze chest and 10 cores.",
            ["rehber.season.t"] = "Season road",
            ["rehber.season.b"] = "A 30-step reward road every month: a win 10, a draw 6, a loss 4 points; quests 25–100. Each step is 100 points: gold, chests, cores, two Epic items at step 20 and a Golden Chest with 3,000 gold at step 30.",
            ["rehber.events.t"] = "Weekly rule and tournament",
            ["rehber.events.b"] = "Monday–Thursday the weekly rule mode: equal power and a rule that changes every week (gifts at 3, 6 and 10 wins). Saturday–Sunday an 8-player tournament: 3 rounds, 2-minute duels; the champion gets a gold chest and the \"Champion\" title.",
            ["rehber.sec.missions"] = "MISSIONS",
            ["rehber.mission.t"] = "Mission levels",
            ["rehber.mission.b"] = "The MISSION button takes you to the levels: clear the floors of robots and vanG, finish the mission, collect stars and gold. Spend gold in the shop on weapons and shields.",
            ["rehber.map.t"] = "Map",
            ["rehber.map.b"] = "The map shows the levels you have reached; you can play any level you have opened again.",
            ["rehber.lives.t"] = "Energy",
            ["rehber.lives.b"] = "Losing a mission level costs 1 energy (3 at most). Energy fills up by itself, one every 12 minutes; beating the newest level fills it all. When it runs out, watch an ad for 1 energy or buy it for 150 gold.",
            ["rehber.sec.gear"] = "SHOP AND GARAGE",
            ["rehber.shop.t"] = "Shop",
            ["rehber.shop.b"] = "Weapons are in tabs by kind (swords, axes, spears, hammers...), shields in a tab of their own. Tap an item's picture: it opens full screen and you can turn it round with your finger. Level up a weapon you own with gold.",
            ["rehber.garage.t"] = "Garage",
            ["rehber.garage.b"] = "Choose foi's head, hair, skin, eye colour, badge and dance. The story badges come with the story; your crown and armour come with your rank.",
