            ["lvl.10.title"] = "Channel Keeper",
            ["lvl.10.vang"] = "My Keeper strikes in threes; angry, it makes it four.",
            ["lvl.20.title"] = "The Presser",
            ["lvl.20.vang"] = "Look up, foi. When you see the shadow it's already too late.",
            ["lvl.30.title"] = "The Pruner",
            ["lvl.30.vang"] = "One blow can't break its leaves. Those who can't combo get crushed.",
            ["lvl.40.title"] = "Queen Bee-01",
            ["lvl.40.vang"] = "My Queen pulls you in with her stinger hook. No one has ever got away.",
            ["lvl.50.title"] = "Shadow Owl",
