            ["lvl.60.vang"] = "When it pounds the ground the whole floor shakes. If you can stay standing.",
            ["lvl.70.title"] = "Sand Worm",
            ["lvl.70.vang"] = "It waits underground. Two seconds: that's all the time I give you.",
            ["lvl.80.title"] = "Drill Giant",
            ["lvl.80.vang"] = "Only a heavy blow pierces its armour. Yours just tickle.",
            ["lvl.90.title"] = "Crane Hook",
            ["lvl.90.vang"] = "Its electric hook shocks you from afar. Catch it if you can.",
            ["lvl.100.title"] = "Deep Eye",
            ["lvl.100.vang"] = "Three stages, three tests. It will ask for everything you've learned.",
            ["lvl.110.title"] = "The Virus",
            ["lvl.110.vang"] = "Every blow makes more of it. Find its core or it never ends.",
            ["lvl.120.title"] = "Ice Bear-X",
            ["lvl.120.vang"] = "It slides in over the ice. Patient enough to wait for it to hit a wall?",
            ["lvl.130.title"] = "Avalanche",
            ["lvl.130.vang"] = "It will push you to the edge. It's a long way down.",
            ["lvl.140.title"] = "Crystal Knight",
            ["lvl.140.vang"] = "Hit it from the front and you hit yourself. After its ultimate its back is open… maybe.",
            ["lvl.150.title"] = "Cave Echo",
            ["lvl.150.vang"] = "You can't see it. When the crystals ring, it's too late.",
            ["lvl.160.title"] = "The Mimic",
            ["lvl.160.vang"] = "It fights with your own moves. Can you get away from yourself?",
            ["lvl.170.title"] = "Acid Spider",
            ["lvl.170.vang"] = "As the floor shrinks, you'll run out of room.",
            ["lvl.180.title"] = "Storm Bird",
            ["lvl.180.vang"] = "It dives from the sky. Whoever stays on the ground loses.",
            ["lvl.190.title"] = "Twin Hawks",
            ["lvl.190.vang"] = "Both at once. Bring one down and the other rages.",
            ["lvl.200.title"] = "Storm General",
            ["lvl.200.vang"] = "One of my generals. The chain lightning awaits you.",
            ["lvl.210.title"] = "Castle Guard Prime",
            ["lvl.210.vang"] = "Six floors, six shield walls. Can you hold out?",
            ["lvl.220.title"] = "Grid Hunter",
            ["lvl.220.vang"] = "It teleports from tile to tile. Lose the rhythm and it's over.",
            ["lvl.230.title"] = "Orbit",
            ["lvl.230.vang"] = "The sky is mine. Meteors will rain on the marked spots.",
            ["lvl.240.title"] = "vanG's Shadow",
            ["lvl.240.vang"] = "My shadow uses your ultimates. Face your own power.",
            ["lvl.250.title"] = "vanG",
            ["lvl.250.vang"] = "Keeper, Army, Heart. You'll never get past all three.",
