            ["story.warden"] = "vanG",
            ["story.end"] = "FINALE",
            ["story.0.0"] = "A dark factory. Rows of cells; in each one a foi with its eyes shut. Cell 7 · Production no. 0001.",
            ["story.0.1"] = "foi's eyes light up.",
            ["story.0.2"] = "You woke up too? We weren't supposed to think!",
            ["story.0.3"] = "Fault detected. Cell 7 will be cleared.",
            ["story.0.4"] = "The door creaks open. foi and Fifi jump into the channel.",
            ["story.0.5"] = "There are thousands of foi in the cells. We can wake them all… if we make it to vanG's Heart.",
            ["story.0.6"] = "The channel leads out of the factory. Quiet… don't wake the Keeper.",
            ["story.1.0"] = "Runaway foi detected. Start the presses.",
            ["story.1.1"] = "Get your shield ready!",
            ["story.2.0"] = "Even the trees are robots! One blow won't do, we need a combo.",
            ["story.3.0"] = "The bees sting one after another. We have to learn to break their streaks.",
            ["story.4.0"] = "In the dark, choose well when to heal. Your hearts are few.",
            ["story.5.0"] = "The rocks will crush you.",
            ["story.5.1"] = "Save up your power, then let it all go at once!",
            ["story.6.0"] = "Something's under the sand… Wait for the right moment.",
            ["story.7.0"] = "These robots have thick armour. We need something heavy.",
            ["story.8.0"] = "Fast and slippery! We have to find a way to catch them.",
            ["story.9.0"] = "No one has come this far.",
            ["story.9.1"] = "Time to use everything we've learned.",
            ["story.10.0"] = "vanG's old server. Something is multiplying in here…",
            ["story.11.0"] = "The floor is ice! Think ahead about where you'll stop.",
            ["story.12.0"] = "The summit will be your grave.",
            ["story.12.1"] = "Mind the edge!",
            ["story.13.0"] = "Hit it from the front and it bounces back. Get behind it!",
            ["story.14.0"] = "I can't see… but I can hear. The crystals are ringing!",
            ["story.15.0"] = "It… fights like us. You have to learn to beat yourself.",
            ["story.16.0"] = "The ground is shrinking. We have to hold our place.",
            ["story.17.0"] = "The attack comes from above! Jump!",
            ["story.18.0"] = "I have two guards. If one falls, the other rages.",
            ["story.19.0"] = "One of vanG's generals! This is a test.",
            ["story.20.0"] = "We have to take the castle floor by floor. Hold on!",
            ["story.21.0"] = "Everything is so fast here. Catch the rhythm!",
            ["story.22.0"] = "Low gravity… Jump and you'll almost fly!",
            ["story.23.0"] = "Meet your own shadow.",
            ["story.23.1"] = "It's a duel rehearsal!",
            ["story.24.0"] = "Why? I gave you everything.",
            ["story.24.1"] = "foi reaches out to the Heart.",
            ["story.25.0"] = "At the end of the three-stage fight the truth comes out: vanG is the very first foi ever made.",
            ["story.25.1"] = "I made thousands of foi so I wouldn't be alone… but I was afraid you'd leave me.",
            ["story.25.2"] = "foi doesn't destroy the Heart; it restarts it.",
            ["story.25.3"] = "The cells are opening! Everyone is free!",
            ["story.25.4"] = "See you in the Arena, foi. Even I never saw that ultimate coming!",
