            ["road.vang.Canyon"] = "The bones and scrap here belong to those before me. You will end up like them.",
            ["road.vang.Ocean"] = "You can't swim against the current, little bug.",
            ["road.vang.Snow"] = "Your system is freezing. You'll make a perfect statue.",
