            ["duel.over"] = "Üstünden!",
            ["rehber.sec.duel"] = "DÜELLO",
            ["rehber.duel.t"] = "Düello nedir?",
            ["rehber.duel.b"] = "Oyunun kalbi düello. Ana sayfadaki DÜELLO butonuna bas: sana uygun bir rakip bulunur (çevrimiçi bir oyuncu ya da bilgisayar) ve yedi düello sahnesinden birinde karşı karşıya gelirsiniz. Senin foi'nin altında mavi, rakibinkinin altında kırmızı bir halka parlar.",
            ["rehber.score.t"] = "Puan ve süre",
            ["rehber.score.b"] = "Düello birkaç dakika sürer. Rakibin canını sıfırlarsan onu yere serersin ve 1 puan alırsın; ikiniz de ortadan yeniden başlarsınız. Süre bitince en çok puanı olan kazanır, kupa ve düello sandığı alır.",
            ["rehber.controls.t"] = "Kontroller",
            ["rehber.controls.b"] = "Sol alttaki çubukla yürü, vuruş butonuyla saldır. Vuruşunun hızı ve gücü taşıdığın silaha göre değişir.",
            ["rehber.power.t"] = "Güç çubuğu, özel güç ve ulti",
            ["rehber.power.b"] = "Her isabetli vuruş sol alttaki üç parçalı güç çubuğunu doldurur. UÇ butonu ve özel hareketin çubuğu harcamaz: her birinin kendi bekleme süresi vardır, sen dövüşürken halkası dolar. Üç parça dolunca ULTİ hazırdır: zaman yavaşlar, foi rakibe peş peşe vurur ve son darbe çok can götürür.",
            ["rehber.combo.t"] = "Kombolar: Güçlü Darbe ve Yere Ser",
            ["rehber.combo.b"] = "Rakibe ara vermeden art arda vurursan kombo sayacı artar. 5 vuruşta GÜÇLÜ DARBE, 8 vuruşta YERE SER butonu belirir; hemen bas. Yere Ser rakibin canının büyük bir kısmını götürür ve onu sırt üstü yere düşürür.",
            ["rehber.breaker.t"] = "Kır",
            ["rehber.breaker.b"] = "Rakip seni art arda vurmaya başlarsa ve güç çubuğunda en az bir parça varsa KIR butonu çıkar. Basınca rakibin saldırısı o an kesilir, rakip geri itilir ve kısa bir süre sersemler: kaçmak ya da karşılık vermek için fırsatın olur.",
            ["rehber.jump.t"] = "Zıpla ve havadan vur",
            ["rehber.jump.b"] = "ZIPLA butonuyla zıpla. Havadayken vurduğun darbe normalden daha çok can götürür ve rakibin kafası yerinden fırlayıp geri gelir. Rakip de zıplayarak vurabilir, dikkat et!",
            ["rehber.defend.t"] = "Kalpler ve kalkanlar",
            ["rehber.defend.b"] = "Her düelloda 3 kalbin ve 3 kalkanın var. Kalp canının bir kısmını geri verir. Kalkan birkaç saniye boyunca iki darbeyi durdurur. Dükkândan aldığın kalkanı taşıyorsan önünden gelen darbeleri de karşılar; karşıladığın darbe can götürmez.",
            ["rehber.stages.t"] = "Düello sahneleri",
            ["rehber.stages.b"] = "Yedi sahne var: Mavi Koru, Buzul Zirvesi, Kızıl Gezegen, Kapadokya, Çiçek Tapınağı, Şövalye Avlusu ve Çöl Sarayı. Her maçta biri rastgele seçilir. Tribünlerde senin taraftarların mavi, rakibinkiler kırmızı.",
            ["rehber.sec.progress"] = "İLERLEME",
            ["rehber.chests.t"] = "Düello sandıkları",
            ["rehber.chests.b"] = "Düello kazandıkça sandık kazanırsın. KASALAR butonundan aç: içinden silah, kalkan ya da altın çıkar; yanında çantan için eşyalar. Beğenmezsen bir kez reklam izleyip içeriği değiştirebilirsin. Bir sandıktan neler çıkabileceğini İÇİNDEKİLER'de görürsün.",
            ["rehber.rank.t"] = "Kupalar ve rütbe",
            ["rehber.rank.b"] = "Kazandıkça kupa toplar, rütbe atlarsın. Rütben sağ üstteki profil butonunda görünür; ona basınca maçlarını ve istatistiklerini görürsün. Yüksek rütbe ordunu da biraz güçlendirir.",
            ["rehber.dlevel.t"] = "Düello Seviyesi",
            ["rehber.dlevel.b"] = "Her düello XP verir: galibiyet 100, beraberlik 60, yenilgi 40; günün ilk galibiyeti +100, maçın küçük meydan okuması +50, geri dönüş galibiyeti +50. Her seviye altın, her 5. seviye Bronz Kasa, 10–50. seviyeler unvan getirir.",
            ["rehber.mastery.t"] = "Silah Ustalığı",
            ["rehber.mastery.b"] = "Bir silahla yaptığın her düello onun ustalığını artırır (galibiyet 3, yenilgi 1). Seviyeleri altın ve Çekirdek getirir; 7. seviyeden itibaren kartında rozet görünür, 10. seviyede ailenin usta unvanı gelir.",
            ["rehber.parts.t"] = "Robot parçaları ve çekirdek",
            ["rehber.parts.b"] = "foi dükkândaki GELİŞTİRME sekmesinde parça parça güçlenir: Gövde can, Kollar hasar, Kabuk zırh verir (her biri 20 seviye). 1–10. seviyeler altınla, 11–20. seviyeler altın ve Çekirdek Parçasıyla alınır. Çekirdek düellodan (galibiyet 3, yenilgi 1), günün ilk galibiyetinden, rütbe atlamaktan ve Altın Kasadan gelir. 5, 10, 15 ve 20. seviyelerde parça foi'nin görünüşünü değiştirir.",
            ["rehber.ceiling.t"] = "Lig Tavanı",
            ["rehber.ceiling.b"] = "Her rütbe kademesinin rütbeli düelloda bir tavanı var: tavanın üstündeki parça seviyesi tavan kadar sayılır, kademenin üstündeki silah o kademenin gücüyle vurur. Tavanda kazananı beceri belirler. Tavanı yükseltmek için rütbe atla. Arkadaş maçlarında güç eşittir: iki taraf da 3. kademe tavanındadır.",
            ["rehber.weapons.t"] = "Silahlar",
            ["rehber.weapons.b"] = "Dört aile var: kılıç (en hızlı), mızrak (menzil), balta (Güçlü Darbe ve Yere Ser %20 daha güçlü) ve ağır silahlar (en büyük vuruş, her isabet sendeletir). Aynı kademedeki silahlar saniyede aynı hasarı verir. Rütbe silahları hep sende kalır.",
            ["rehber.quests.t"] = "Görevler",
            ["rehber.quests.b"] = "Tüm görevler tek GÖREVLER ekranında: günde üç (bir düello görevi, bir bölüm görevi ve ikisinden biri olan bir tane daha) ve haftada üç büyük görev. Bitirdiklerinin altınını almayı unutma.",
            ["rehber.login.t"] = "Giriş takvimi",
            ["rehber.login.b"] = "Her gün gir, hediyeni al: 200 altın, Basit Kasa, 300 altın, 10 Çekirdek, Bronz Kasa, 500 altın ve Altın Kasa. Bir gün kaçırırsan bir şey kaybetmezsin: takvim kaldığın yerden devam eder. Arkadaş maçları günün ilk üç maçında altın verir, kasa vermez.",
            ["rehber.friends.t"] = "Arkadaşlar",
            ["rehber.friends.b"] = "ARKADAŞ butonundan arkadaşını adıyla ya da 6 haneli arkadaş koduyla ekle. Çevrimiçiyse düelloya davet et; değilse onun kopyasıyla dövüş (rütbe puanı değişmez, aranızdaki skor sayılır). Kaybedersen İNTİKAM AL. Davetinle gelen biri Dünya 1'i bitirince ikinize de Bronz Kasa ve 10 Çekirdek.",
            ["rehber.season.t"] = "Sezon Yolu",
            ["rehber.season.b"] = "Her ay 30 basamaklı bir ödül yolu: galibiyet 10, beraberlik 6, yenilgi 4 puan; görevler 25–100 puan. Her basamak 100 puan; altın, kasa, Çekirdek, 20. basamakta 2 Efsane eşya ve 30. basamakta Altın Kasa ile 3.000 altın.",
            ["rehber.events.t"] = "Haftalık kural ve turnuva",
            ["rehber.events.b"] = "Pazartesi–Perşembe haftalık kural modu: eşit güç ve her hafta değişen bir kural (3, 6, 10 galibiyette ödül). Cumartesi–Pazar 8 kişilik turnuva: 3 tur, 2 dakikalık maçlar; şampiyona Altın Kasa ve \"Şampiyon\" unvanı.",
            ["rehber.sec.missions"] = "GÖREV YAP",
            ["rehber.mission.t"] = "Görev bölümleri",
            ["rehber.mission.b"] = "GÖREV YAP butonu seni bölümlere götürür: katları robotlardan ve vanG'lerden temizle, görevi bitir, yıldız ve altın topla. Altınlarla dükkândan silah ve kalkan alırsın.",
            ["rehber.map.t"] = "Harita",
            ["rehber.map.b"] = "Harita ulaştığın bölümleri gösterir; açtığın her bölümü yeniden oynayabilirsin.",
            ["rehber.lives.t"] = "Enerji",
            ["rehber.lives.b"] = "Görev bölümlerini kaybetmek 1 enerji harcar (en çok 3). Enerji 12 dakikada bir kendiliğinden dolar; en yeni bölümü geçmek hepsini doldurur. Bitince reklam izleyip 1 enerji alabilir ya da 150 altınla satın alabilirsin.",
            ["rehber.sec.gear"] = "DÜKKÂN VE GARAJ",
            ["rehber.shop.t"] = "Dükkân",
            ["rehber.shop.b"] = "Silahlar türlerine göre sekmelerde (kılıç, balta, mızrak, çekiç...), kalkanlar ayrı bir sekmede. Bir ürünün resmine dokun: tam ekran açılır, parmağınla çevirip her yanından bakarsın. Aldığın silahı altınla seviye seviye geliştirebilirsin.",
            ["rehber.garage.t"] = "Garaj",
            ["rehber.garage.b"] = "foi'nin kafasını, saçını, ten rengini, göz rengini, rozetini ve dansını seç. Hikâye rozetleri hikâyeyle gelir; tacını ve zırhını rütben getirir.",
            ["duel.jump"] = "ZIPLA",
            ["duel.airHit"] = "Havadan vuruş!",
            ["duel.finished"] = "BİTİRİŞ!",
