            ["story.kuzgun"] = "KUZGUN",
            ["story.chapter"] = "BÖLÜM {0}  ·  {1}",
            ["story.bip"] = "FİFİ",
            ["story.thief"] = "KUZGUN",
            ["story.firstObserver"] = "KUZGUN (CL-1)",
            ["story.skip"] = "GEÇ",
            ["story.tap"] = "Devam için dokun >",
            ["story.floor"] = "KAT {0}",
            ["story.robot"] = "FOI",
            ["story.warden"] = "vanG",
            ["story.end"] = "FİNAL",
            ["story.0.0"] = "Karanlık bir fabrika. Sıra sıra hücreler; her birinde gözleri kapalı bir foi. Hücre 7 · Üretim no. 0001.",
            ["story.0.1"] = "foi'nin gözleri yanar.",
            ["story.0.2"] = "Sen de mi uyandın? Bizim düşünmememiz gerekiyordu!",
            ["story.0.3"] = "Arıza tespit edildi. Hücre 7 temizlenecek.",
            ["story.0.4"] = "Kapı aralanır. foi ve Fifi kanala atlar.",
            ["story.0.5"] = "Hücrelerde binlerce foi var. Hepsini uyandırabiliriz… vanG'ün Kalbi'ne kadar gidersek.",
            ["story.0.6"] = "Kanal fabrikanın dışına çıkıyor. Sessiz ol… Bekçi uyanmasın.",
            ["story.1.0"] = "Kaçak foi tespit edildi. Presleri çalıştırın.",
            ["story.1.1"] = "Kalkanı hazırla!",
            ["story.2.0"] = "Ağaçlar bile robot! Tek vuruş yetmez, seri yapmalıyız.",
            ["story.3.0"] = "Arılar ardı ardına sokuyor. Serilerini kırmayı öğrenmeliyiz.",
            ["story.4.0"] = "Karanlıkta ne zaman iyileşeceğini iyi seç. Kalbin sınırlı.",
            ["story.5.0"] = "Kayalar sizi ezecek.",
            ["story.5.1"] = "Gücünü biriktir, sonra hepsini bir anda bırak!",
            ["story.6.0"] = "Kumun altında bir şey var… Doğru anı bekle.",
            ["story.7.0"] = "Bu robotların zırhı kalın. Ağır bir şeye ihtiyacımız var.",
            ["story.8.0"] = "Hızlı ve kaçak! Onları yakalamanın yolunu bulmalıyız.",
            ["story.9.0"] = "Buraya kadar gelen olmadı.",
            ["story.9.1"] = "Öğrendiğimiz her şeyi kullanma zamanı.",
            ["story.10.0"] = "vanG'ün eski sunucusu. Burada bir şey çoğalıyor…",
            ["story.11.0"] = "Zemin buz! Nerede duracağını önceden düşün.",
            ["story.12.0"] = "Zirve sizin mezarınız olacak.",
            ["story.12.1"] = "Kenara dikkat!",
            ["story.13.0"] = "Önden vurursan geri döner. Arkasına geç!",
            ["story.14.0"] = "Göremiyorum… ama duyabiliyorum. Kristaller çınlıyor!",
            ["story.15.0"] = "O… bizim gibi dövüşüyor. Kendini yenmeyi öğrenmelisin.",
            ["story.16.0"] = "Alan daralıyor. Yerimizi korumalıyız.",
            ["story.17.0"] = "Saldırı yukarıdan geliyor! Zıpla!",
            ["story.18.0"] = "İki muhafızım var. Biri düşerse diğeri öfkelenir.",
            ["story.19.0"] = "vanG'ün generallerinden biri! Bu bir sınav.",
            ["story.20.0"] = "Kaleyi kat kat geçmemiz gerek. Dayan!",
            ["story.21.0"] = "Burada her şey çok hızlı. Ritmi yakala!",
            ["story.22.0"] = "Yerçekimi az… Zıplarsan uçacak gibisin!",
            ["story.23.0"] = "Kendi gölgenle tanış.",
            ["story.23.1"] = "Bu bir düello provası!",
            ["story.24.0"] = "Neden? Size her şeyi ben verdim.",
            ["story.24.1"] = "foi elini Kalbe uzatır.",
            ["story.25.0"] = "Üç aşamalı dövüşün sonunda gerçek ortaya çıkar: vanG, üretilen ilk foi'dir.",
            ["story.25.1"] = "Yalnız kalmamak için binlerce foi ürettim… ama beni terk edeceğinizden korktum.",
