            ["lvl.1.title"] = "İlk Adım",
            ["lvl.1.vang"] = "Hücre-7, kalibrasyon testi başlıyor. Başarı beklentisi: %100. Hata payı yok.",
            ["lvl.1.help"] = "Psst, ben Fifi! Ekranı kaydır, foi o yöne yürür. Parlayanları topla!",
            ["lvl.1.goal"] = "3 altın topla",
            ["lvl.1.hook"] = "vanG: «Kalibrasyon %1 tamamlandı. Devam.»",
            ["lvl.2.title"] = "Kırmızı Artı",
            ["lvl.2.vang"] = "Bu tavanı senin için sandıkla doldurdum. Tepki süren ölçülüyor, Hücre-7.",
            ["lvl.2.help"] = "Yerde kırmızı artı görürsen hemen o karodan çık! Sandık oraya düşer.",
            ["lvl.2.goal"] = "5 altın topla",
            ["lvl.3.title"] = "Gri Fırça",
            ["lvl.3.vang"] = "Senin tek işin gri boyamak. Bu odayı kusursuzluğun için tasarladım.",
            ["lvl.3.help"] = "Bastığın her karo boyanır. Sıra sıra git, artı çıkınca kenara çekil!",
            ["lvl.3.goal"] = "15 karonun hepsini boya",
            ["lvl.3.hook"] = "Son karoya basınca garip bir şey olur: karo bir anlığına sarı yanıp söner.",
            ["lvl.4.title"] = "Altın Damlası",
            ["lvl.4.vang"] = "Ödül turu. Altınları sana ben yağdırıyorum; minnet beklemiyorum, Hücre-7.",
            ["lvl.4.help"] = "Ekrana bir kez dokun, zıplarsın! Taşların üstünden atla, altınlar orada!",
            ["lvl.4.goal"] = "20 sn içinde yağan altınlardan en az 12'sini topla",
            ["lvl.4.hook"] = "Yağmur biterken foi'nin ayağının altındaki karo griye dönmez: parlak, sıcak bir sarı olarak kalır.",
            ["lvl.5.title"] = "Sarı Karo",
            ["lvl.5.vang"] = "Anomali tespit edildi. Odayı griye boya. Hemen. Hata olasılığı: %0,01.",
            ["lvl.5.help"] = "Vay, sarı! Gördün mü? Boyamaya devam et, iki artıya birden dikkat!",
            ["lvl.5.goal"] = "25 karonun hepsini boya",
            ["lvl.5.hook"] = "Oda sapsarı parlarken vanG'ün gözü kısılır: «Bu bir boya değil. Bu bir hata. Tarama başlatılıyor.»",
            ["lvl.6.title"] = "Hafıza Çipleri",
            ["lvl.6.vang"] = "Sandıklarımı ağırlaştırdım; düştükleri karo kırılır. Tarama odasına gel, Hücre-7.",
            ["lvl.6.help"] = "Kenarı çatlak karo delik demek! Üstünden zıpla ya da etrafından dolaş.",
            ["lvl.6.goal"] = "3 hafıza çipi topla ve tarama kapısına ulaş",
            ["lvl.6.hook"] = "Son çipte Fifi donakalır: «Bu… bir gün batımı. Bir zamanlar her şey renkliydi, foi.»",
            ["lvl.7.title"] = "İmha Testi",
            ["lvl.7.vang"] = "Kalibrasyon iptal. Bu artık imha testi. Hayatta kalma olasılığın: %4.",
            ["lvl.7.help"] = "Sandıklar hızlandı ama artılar hâlâ önceden yanıyor. Gözün yerde olsun!",
            ["lvl.7.goal"] = "8 altın topla",
            ["lvl.7.hook"] = "Fifi test duvarında aralık kalmış bir servis kapısı görür: «Oradan çıkabiliriz!»",
            ["lvl.8.title"] = "Üç Oda",
            ["lvl.8.vang"] = "Kapılar açık mı? Elbette. Her odayı kaçacağın sırayla ben dizdim.",
            ["lvl.8.help"] = "Her kapının önüne sandık düşüyor. Artıyı bekle, sandık insin, sonra geç!",
            ["lvl.8.goal"] = "3 odadan geçip son kapıya 45 sn içinde ulaş",
            ["lvl.8.hook"] = "Üçüncü kapının ardında vidalı bir bakım kapağı var; kapı foi'nin arkasından kilitlenir.",
            ["lvl.9.title"] = "Kilitli Oda",
            ["lvl.9.vang"] = "Bu odanın çıkışı yok. Bekle ve ezil; işlem 30 saniye sürecek.",
            ["lvl.9.help"] = "Sen dayan, ben vidaları sökerim! Ortada kal, kenarlar çabuk delik doluyor!",
            ["lvl.9.goal"] = "30 sn dayan",
            ["lvl.9.hook"] = "Son vida yere düşer, kapak gıcırdar. Fifi: «Açıldı! Hadi, kanala!»",
            ["lvl.10.help"] = "Üç şerit var! Artısız şeride kay, çatlak karo görürsen zıpla!",
            ["lvl.11.title"] = "Fitilli Hediye",
            ["lvl.11.vang"] = "Kaçan Leke'ye hoş geldin hediyesi: fitilli bloklar. Paketlemesi bana ait.",
            ["lvl.11.help"] = "Turuncu artı bomba demek! Artının dışına çık, çapraz köşe güvenli!",
            ["lvl.11.goal"] = "5 altın topla",
            ["lvl.12.title"] = "Sarı Kıvılcım",
            ["lvl.12.vang"] = "Her sarı karon bir hata kaydı. Kayıtları bombayla temizleyeceğim.",
            ["lvl.12.help"] = "Bomba düşerken boyamaya ara ver, çapraza geç, sonra kaldığın yerden!",
            ["lvl.12.goal"] = "25 karonun hepsini boya",
            ["lvl.12.hook"] = "Boyanan holün ucunda montaj holünün kapısı açılır; zemin delik deşik.",
            ["lvl.13.title"] = "Delik Deşik",
            ["lvl.13.vang"] = "Montaj holüne hoş geldin. Zemini %40 oranında deldim; gerisi senin şansın.",
            ["lvl.13.help"] = "Patlayan bomba karoyu kırar. Çatlak kenara basma, zıplayarak aş!",
            ["lvl.13.goal"] = "7 altın topla",
            ["lvl.13.hook"] = "Bant kapısı açılır; arkasında boş bir cevher vagonu duruyor.",
            ["lvl.14.title"] = "Altın Vagonu",
            ["lvl.14.vang"] = "Depomdan geçiyorsun. Altınlarımı say, Leke; hepsinin kaydını tutuyorum.",
            ["lvl.14.help"] = "Yaşasın, vagon! Sadece sağa sola kay, altınlar kucağına düşer!",
            ["lvl.14.goal"] = "Yolculuk boyunca 20 altından en az 14'ünü topla",
            ["lvl.14.hook"] = "Vagon depodan çıkarken raflardan bir gölge atlar ve altın torbası şıngırdar.",
            ["lvl.15.title"] = "Pelerinli Gölge",
            ["lvl.15.vang"] = "Kasamda bir hırsız var. İkinizi aynı odaya kapattım; biri kalacak.",
            ["lvl.15.help"] = "Maskeli hızlı ama hep en yakın altına koşuyor. Uzaktakini sen kap!",
            ["lvl.15.goal"] = "Kuzgun 8 altına ulaşmadan 8 altın topla",
            ["lvl.15.hook"] = "Kuzgun son altını kapıp duvardaki boruya atlar, giderken döner: «Acele et, Leke.»",
            ["lvl.16.title"] = "Gri Kardeşler",
            ["lvl.16.vang"] = "Onlar kusursuz. Sen hatalı olansın. Bandımı Süpürgeç'le koruyorum.",
            ["lvl.16.help"] = "Sarı çizgi Süpürgeç'in rayı! Raydan çık, geçince arkasından yürü.",
            ["lvl.16.goal"] = "Bandın yanındaki 4 etiket karosuna bas ve çıkışa ulaş",
            ["lvl.16.hook"] = "Dört etiketin hepsinde aynı yazı: «Boş gövde — renk yok.» Fifi fısıldar: «Senin gövdende ne var ki onlarda yok?»",
            ["lvl.17.title"] = "Kırmızı Sıra",
            ["lvl.17.vang"] = "Tek tek ezmek verimsiz. Artık sıra sıra eziyorum. Verim artışı: %600.",
            ["lvl.17.help"] = "Bütün sıra kırmızıysa yeşil kalan kareye koş! Yeşil hep güvenli!",
            ["lvl.17.goal"] = "6 altın topla",
            ["lvl.17.hook"] = "Pres salonunun alarmı öter; yan bant hattının kapısı açılır.",
            ["lvl.18.title"] = "Bant Koşusu",
            ["lvl.18.vang"] = "Alarm benim fikrimdi. Koridoru seni Veri Kapısı'na götürsün diye uzattım.",
            ["lvl.18.help"] = "Bomba şeritleri kapatıyor. Artının köşesinden geç, Süpürgeç karşıdan geliyor!",
            ["lvl.18.goal"] = "Koridorun sonuna 45 sn içinde ulaş",
            ["lvl.18.hook"] = "Koridorun sonunda kapısı kapalı bir bekleme odası; duvarında «VERİ KAPISI» yazıyor.",
            ["lvl.19.title"] = "Bekleme Odası",
            ["lvl.19.vang"] = "Kapıyı açmadan önce seni yoracağım. Kırk saniye, sıra sıra.",
            ["lvl.19.help"] = "Önce sıra uyarısına bak, sonra bombaya. Yeşili bul, gerekirse çapraza kay!",
            ["lvl.19.goal"] = "40 sn dayan",
            ["lvl.19.hook"] = "Oda susar, Veri Kapısı aralanır; önünde dev bir pres kolu doğrulur.",
            ["lvl.20.help"] = "Kol inince yere saplanıyor! O an yanındaki sarı düğmeye bas!",
            ["lvl.21.title"] = "Yeşil Yapışkan",
            ["lvl.21.vang"] = "Bu ormanı senin için yapıştırdım. Burada her adımın iki adım sürer.",
            ["lvl.21.help"] = "Yeşil tüylü karo yapışkan! Ya yosunsuz yoldan git ya da iki kez kaydır.",
            ["lvl.21.goal"] = "6 altın topla",
            ["lvl.22.title"] = "Tüten Karo",
            ["lvl.22.vang"] = "Renkli ağaçlar yanıcıdır. Karolarını senin için ısıttım; basarsan yanarsın.",
            ["lvl.22.help"] = "Duman çıkan karo birazdan yanar! Basma, üstünden zıpla ya da bekle.",
            ["lvl.22.goal"] = "6 altın topla",
            ["lvl.23.title"] = "Yosun ve Kor",
            ["lvl.23.vang"] = "Yosun seni tutar, ateş seni yakar. İkisini yan yana dizdim.",
            ["lvl.23.help"] = "Yosunun yanındaki karo tütüyorsa dur! Önce alev geçsin, sonra çık.",
            ["lvl.23.goal"] = "8 altın topla",
            ["lvl.23.hook"] = "Patikanın sonunda güneş alan, sessiz bir açıklık görünür.",
            ["lvl.24.title"] = "Yaprak Yağmuru",
            ["lvl.24.vang"] = "Bu açıklığı unutmuşum. Hata payı %0,2. Birazdan düzelteceğim.",
            ["lvl.24.help"] = "Kelebek! Ah, altın da var! Halkalara koş, burada hiçbir şey yanmıyor!",
            ["lvl.24.goal"] = "25 sn içinde en az 15 altın topla",
            ["lvl.24.hook"] = "Açıklığın kenarından bir vızıltı yaklaşır: bir Silgi-bot geçtiği yeri griye çeviriyor.",
            ["lvl.25.title"] = "Silgi-bot",
            ["lvl.25.vang"] = "Silgi-botum yavaş ama yorulmaz. Senin boyan, benim silgim. Bakalım.",
            ["lvl.25.help"] = "Soluk gri çizgi onun yolu! Önünden kaç, üstüne zıplarsan 5 sn devrilir!",
            ["lvl.25.goal"] = "36 karonun en az 30'unu aynı anda boyalı hale getir",
            ["lvl.25.hook"] = "Devrilen Silgi-bot'un kırık kapağından buz mavisi bir ışık sızar; ışık ormanın derinini gösteriyor.",
            ["lvl.26.title"] = "Buz Kafes",
            ["lvl.26.vang"] = "O kafesi ben kilitledim. Dört kilit, dört ateş. Açamazsın, Leke.",
            ["lvl.26.help"] = "Dört köşedeki kollar kafesi eritir! Yosunsuz git, tüten karoyu bekle!",
            ["lvl.26.goal"] = "4 köşedeki eritme kolunu çevir ve kafesi aç",
